        login((cache.get(java.md5Encode16(Get('url') + "Account_1")) && String(cache.get(java.md5Encode16(Get('url') + "Account_1"))).length > 0) ? (Put(JSON.stringify('【登录提示】\n\n┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋' + '\n已退出账号：' + cache.get(java.md5Encode16(Get('url') + "Account_1")) + '\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛'))) : ('【登录提示】' + '\n\n请输入账号和密码'));
        var headers = JSON.parse(cache.get(java.md5Encode16(Get('url') + "headers")).replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/uccenter'));
        var option = {
            "method": "GET",
            "headers": headers
        };
        java.ajax(Get('url') + '/logout,' + JSON.stringify(option));
        cookie.removeCookie(Get('url'));
        cache.put(java.md5Encode16(Get('url') + "Account_1"),'');
        return;
    } else if (Account == '') {
        login('【登录提示】' + '\n\n请输入账号');
        return;
    } else if (Password == '') {
        login('【登录提示】' + '\n\n请输入密码');
        return;
    } else {
            cookie.removeCookie(Get('url'));
            var headers = JSON.parse(cache.get(java.md5Encode16(Get('url') + "headers")).replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/login'));
            var option = {
                "method": "GET",
                "headers": headers
            };
            Code = java.getVerificationCode(Get('url') + '/captcha,' + JSON.stringify(option));
            let ck = cookie.getCookie(Get('url'));
            var requestBody = 'username=' + Account + '&password=' + Password + '&captcha=' + Code;
            var headers = JSON.parse(cache.get(java.md5Encode16(Get('url') + "headers")).replace('"Referer":"' + Get('url'), '"Referer":"' + Get('url') + '/login').replace('"proxy"', '"Cookie":"' + ck + '","proxy"'));
            var option = {
                "method": "POST",
                "body": String(requestBody),
                "headers": headers
            };
            Response = java.ajax(Get('url') + '/login,' + JSON.stringify(option));
            if (Response.includes('成功') && Account) {
                cache.put(java.md5Encode16(Get('url') + "Account_1"), Account);
                login(Put(JSON.stringify('【登录提示】\n\n┏┅━┅━┅━┅━┅━┅━┅━┅━┅┓\n┋┋' + '\n账号：' + Account + '\n┋┋' + '\n❤️登录成功❤️\n┋┋' + '\n┗┅━┅━┅━┅━┅━┅━┅━┅━┅┛')));
